"""Independent audit of notes/palindromic_h_c.md (claims P0, E0, E1, E2, I, G, S').

Written from scratch: it does not import any other script of this repository.

  * Posets up to isomorphism are generated by adding a new maximal element
    above an order ideal, and deduplicated by a brute-force canonical form
    (minimum relation code over the permutations that respect an invariant
    refinement).
  * h_C is computed straight from the Moebius definition
        Omega_C(P, m) = sum_{pi in OP(P)} (-1)^{|pi|-1} mu(pi, 1^) C(m, |pi|),
    OP(P) = set partitions with acyclic quotient digraph, ordered by
    refinement, mu computed by the defining recursion over coarsenings.
    Then h_C is read off from sum_m Omega_C(P, m) x^m (1 - x)^{n+1}
    = sum_j h_j x^{j+1}, and trimmed.
  * Every other quantity (J, s(K, m), Omega-bar_C, anchored maps) is a literal
    count written here.

Usage:  python3 audit_palindromic_h_c.py --mobmax 7 --endmax 8 [--litmax 6]
Exit status 0 iff every CHECK has 0 bad and every CONTROL is refuted somewhere.
"""
import argparse
import itertools
import sys
import time
from math import comb

# ---------------------------------------------------------------- posets

def closure(n, rel):
    """rel: set of (a, b) with a < b in P. Return transitive closure as frozenset."""
    lt = [[False] * n for _ in range(n)]
    for a, b in rel:
        lt[a][b] = True
    for k in range(n):
        for i in range(n):
            if lt[i][k]:
                for j in range(n):
                    if lt[k][j]:
                        lt[i][j] = True
    return frozenset((i, j) for i in range(n) for j in range(n) if lt[i][j])


def invariants(n, rel):
    down = [0] * n
    up = [0] * n
    for a, b in rel:
        up[a] += 1
        down[b] += 1
    lab = [(down[x], up[x]) for x in range(n)]
    for _ in range(3):
        nb = []
        for x in range(n):
            below = sorted(lab[a] for a, b in rel if b == x)
            above = sorted(lab[b] for a, b in rel if a == x)
            nb.append((lab[x], tuple(below), tuple(above)))
        keys = sorted(set(nb))
        lab = [keys.index(v) for v in nb]
    return lab


def canon(n, rel):
    lab = invariants(n, rel)
    classes = {}
    for x in range(n):
        classes.setdefault(lab[x], []).append(x)
    order = sorted(classes)
    groups = [classes[k] for k in order]
    best = None
    for perms in itertools.product(*[itertools.permutations(g) for g in groups]):
        seq = [x for p in perms for x in p]          # new position -> old element
        pos = [0] * n
        for i, x in enumerate(seq):
            pos[x] = i
        code = tuple(sorted((pos[a], pos[b]) for a, b in rel))
        if best is None or code < best:
            best = code
    return (tuple(lab[x] for x in sorted(range(n), key=lambda y: lab[y])), best)


def from_canon(n, key):
    return frozenset(key[1])


def order_ideals(n, rel):
    """All down-closed subsets of range(n), as bitmasks."""
    below = [0] * n
    for a, b in rel:
        below[b] |= 1 << a
    out = []
    for S in range(1 << n):
        ok = True
        for x in range(n):
            if S >> x & 1 and below[x] & ~S:
                ok = False
                break
        if ok:
            out.append(S)
    return out


def all_posets(nmax):
    """dict n -> list of relation sets (one per isomorphism class)."""
    res = {1: [frozenset()]}
    for n in range(2, nmax + 1):
        seen = {}
        for rel in res[n - 1]:
            for S in order_ideals(n - 1, rel):
                new = set(rel) | {(a, n - 1) for a in range(n - 1) if S >> a & 1}
                new = closure(n, new)
                key = canon(n, new)
                if key not in seen:
                    seen[key] = new
        res[n] = list(seen.values())
    return res

# ---------------------------------------------------------------- structure

def components(n, rel):
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    for a, b in rel:
        parent[find(a)] = find(b)
    comp = {}
    for x in range(n):
        comp.setdefault(find(x), []).append(x)
    return sorted(comp.values())


def restrict(rel, K):
    idx = {x: i for i, x in enumerate(K)}
    return len(K), frozenset((idx[a], idx[b]) for a, b in rel if a in idx and b in idx)


def longest_chain(n, rel):
    """delta(x) = size of a longest chain with top x; returns (L, delta)."""
    below = [[a for a, b in rel if b == x] for x in range(n)]
    delta = [0] * n
    # elements in a linear extension: sort by number below (a valid topological order)
    order = sorted(range(n), key=lambda x: len(below[x]))
    for x in order:
        delta[x] = 1 + max((delta[a] for a in below[x]), default=0)
    return (max(delta) if n else 0), delta


def is_graded(n, rel):
    """Every maximal chain has the same number of elements."""
    succ = [[b for a, b in rel if a == x] for x in range(n)]
    cover = [[y for y in succ[x] if not any((z, y) in rel for z in succ[x])] for x in range(n)]
    mins = [x for x in range(n) if not any(b == x for a, b in rel)]
    lengths = set()

    def go(x, k):
        if not cover[x]:
            lengths.add(k)
            return
        for y in cover[x]:
            go(y, k + 1)
    for x in mins:
        go(x, 1)
    return len(lengths) == 1


def num_ideals(n, rel):
    return len(order_ideals(n, rel))


def strict_maps(n, rel, m):
    """All strictly order-preserving f : P -> [m], as tuples, by backtracking."""
    below = [[a for a, b in rel if b == x] for x in range(n)]
    above = [[b for a, b in rel if a == x] for x in range(n)]
    order = sorted(range(n), key=lambda x: len(below[x]))
    f = [0] * n
    out = []

    def go(i):
        if i == n:
            out.append(tuple(f))
            return
        x = order[i]
        lo = 1 + max((f[a] for a in below[x]), default=0)
        for v in range(lo, m + 1):
            f[x] = v
            go(i + 1)
        f[x] = 0
    go(0)
    return out


def count_strict(n, rel, m):
    return len(strict_maps(n, rel, m))


def count_strict_allmaps(n, rel, m):
    """Literal count over all m^n maps (small cases only)."""
    c = 0
    for f in itertools.product(range(1, m + 1), repeat=n):
        if all(f[a] < f[b] for a, b in rel):
            c += 1
    return c


def clusters(comps, T):
    """All T-free clusters: nonempty unions of components other than T (as element sets)."""
    others = [K for K in comps if K is not T]
    out = []
    for k in range(1, len(others) + 1):
        for sub in itertools.combinations(others, k):
            out.append([x for K in sub for x in K])
    return out


def satisfies_DT(f, n, cl):
    for U in cl:
        Us = set(U)
        rest = [f[x] for x in range(n) if x not in Us]
        if min(f[x] for x in U) >= max(rest):
            return False
    return True


def anchored(f, n, cl):
    for U in cl:
        Us = set(U)
        rest = [f[x] for x in range(n) if x not in Us]
        if min(f[x] for x in U) > max(rest):
            return False
    return True


def omegabar_literal(n, rel, comps, T, m):
    cl = clusters(comps, T)
    return sum(1 for f in strict_maps(n, rel, m) if satisfies_DT(f, n, cl))


def weak_maps(n, rel, m):
    below = [[a for a, b in rel if b == x] for x in range(n)]
    order = sorted(range(n), key=lambda x: len(below[x]))
    f = [0] * n
    out = []

    def go(i):
        if i == n:
            out.append(tuple(f))
            return
        x = order[i]
        lo = max((f[a] for a in below[x]), default=1)
        for v in range(lo, m + 1):
            f[x] = v
            go(i + 1)
        f[x] = 0
    go(0)
    return out

# ---------------------------------------------------------------- Moebius Omega_C

def set_partitions_rgs(k):
    """All restricted growth strings of length k."""
    out = []

    def go(s, mx):
        if len(s) == k:
            out.append(tuple(s))
            return
        for v in range(mx + 2):
            s.append(v)
            go(s, max(mx, v))
            s.pop()
    if k == 0:
        return [()]
    go([0], 0)
    return out


RGS = {}


def rgs(k):
    if k not in RGS:
        RGS[k] = set_partitions_rgs(k)
    return RGS[k]


def normalize(labels):
    mp = {}
    out = []
    for v in labels:
        if v not in mp:
            mp[v] = len(mp)
        out.append(mp[v])
    return tuple(out)


def acyclic_quotient(n, rel, part):
    k = max(part) + 1
    edges = [set() for _ in range(k)]
    for a, b in rel:
        if part[a] != part[b]:
            edges[part[a]].add(part[b])
    indeg = [0] * k
    for u in range(k):
        for v in edges[u]:
            indeg[v] += 1
    stack = [u for u in range(k) if indeg[u] == 0]
    seen = 0
    while stack:
        u = stack.pop()
        seen += 1
        for v in edges[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                stack.append(v)
    return seen == k


def omega_c_coeffs(n, rel):
    """a[k] = sum over pi in OP(P) with k blocks of (-1)^{k-1} mu(pi, 1^).
    Also returns whether every term (-1)^{k-1} mu is >= 0."""
    OP = [p for p in rgs(n) if acyclic_quotient(n, rel, p)]
    OPset = set(OP)
    mu = {}
    top = tuple([0] * n)
    for p in sorted(OP, key=lambda p: max(p)):          # coarse first
        k = max(p) + 1
        if p == top:
            mu[p] = 1
            continue
        s = 0
        for q in rgs(k):                                   # partitions of the blocks of p
            if max(q) + 1 == k:
                continue                                   # q discrete gives p itself
            sigma = normalize([q[p[x]] for x in range(n)])
            if sigma in OPset:
                s += mu[sigma]
        mu[p] = -s
    a = [0] * (n + 1)
    signs_ok = True
    for p, v in mu.items():
        k = max(p) + 1
        t = (-1) ** (k - 1) * v
        if t < 0:
            signs_ok = False
        a[k] += t
    return a, signs_ok


def omega_c(a, m):
    return sum(a[k] * comb(m, k) for k in range(len(a))) if m >= 0 else \
        sum(a[k] * gen_binom(m, k) for k in range(len(a)))


def gen_binom(x, k):
    num = 1
    for i in range(k):
        num *= (x - i)
    den = 1
    for i in range(1, k + 1):
        den *= i
    return num // den


def h_from_omega(n, vals):
    """vals[m] = Omega_C(P, m), m = 0..n+1. sum_m vals[m] x^m (1-x)^{n+1} = sum_j h_j x^{j+1}."""
    N = len(vals)
    series = [0] * N
    for m in range(N):
        for t in range(0, n + 2):
            if m + t < N:
                series[m + t] += vals[m] * comb(n + 1, t) * (-1) ** t
    h = series[1:N]
    while h and h[-1] == 0:
        h.pop()
    return h

# ---------------------------------------------------------------- main

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--mobmax", type=int, default=7)
    ap.add_argument("--endmax", type=int, default=8)
    ap.add_argument("--litmax", type=int, default=6)
    args = ap.parse_args()
    t0 = time.time()
    nmax = max(args.mobmax, args.endmax)
    posets = all_posets(nmax)
    print("posets per n:", {n: len(posets[n]) for n in range(1, nmax + 1)})

    checks = {}
    controls = {}

    def chk(name, ok):
        c = checks.setdefault(name, [0, 0])
        c[0] += 1
        if not ok:
            c[1] += 1

    def ctl(name, refuted):
        c = controls.setdefault(name, [0, 0])
        c[0] += 1
        if refuted:
            c[1] += 1

    stats = {"hd>=2": 0, "hd=1": 0, "gap_attained": 0, "pal_disc": {}}
    examples = {}

    for n in range(2, nmax + 1):
        for rel in posets[n]:
            comps = components(n, rel)
            r = len(comps)
            L, delta = longest_chain(n, rel)
            subs = [restrict(rel, K) for K in comps]
            LK = [longest_chain(*s)[0] for s in subs]
            iso = sum(1 for K in comps if len(K) == 1)
            nonsing = [s for K, s in zip(comps, subs) if len(K) > 1]
            J = num_ideals(n, rel)
            JK = [num_ideals(*s) for s in subs]
            connected = r == 1
            graded = is_graded(n, rel)
            T = comps[LK.index(L)]          # a component containing an L-chain
            cl = clusters(comps, T)

            # ---- ingredient I on every poset (connected or not), n <= endmax
            if n <= args.endmax:
                sK = count_strict(n, rel, L + 1)
                chk("[I] s(P, L+1) >= J(P), every P", sK >= J)
                if connected:
                    chk("[I=] connected: s(P,L+1) = J(P) iff graded (COMPUTED only)", (sK == J) == graded)
                if n <= args.litmax:
                    # the explicit injection g -> g + delta - 1 is strict, lands in [L+1], injective
                    imgs = set()
                    ok = True
                    for g in weak_maps(n, rel, 2):
                        f = tuple(g[x] + delta[x] - 1 for x in range(n))
                        if not all(f[a] < f[b] for a, b in rel) or max(f) > L + 1 or min(f) < 1:
                            ok = False
                        imgs.add(f)
                    ok = ok and len(imgs) == J
                    chk("[I-inj] g -> g + delta - 1 strict, into [L+1], injective (n<=litmax)", ok)

            # ---- end coefficients by literal counts (independent of h), n <= endmax
            if n <= args.endmax:
                anch2 = sum(1 for f in weak_maps(n, rel, 2) if anchored(f, n, cl))
                # Omega_C(P,1)=h0 and Omega_C(P,2)=(n+1)h0+h1 (B+; used only as a cross-check here)
                h0_lit = sum(1 for f in weak_maps(n, rel, 1) if anchored(f, n, cl))
                h1_lit = anch2 - (n + 1) * h0_lit
                chk("[E0-lit] anchored maps into [1] = 1", h0_lit == 1)
                chk("[E0-lit] anchored maps into [2] = J - 2^{r-1} + 1", anch2 == J - 2 ** (r - 1) + 1)
                if L >= 2:
                    obL = omegabar_literal(n, rel, comps, T, L)
                    E1 = (L - 1) ** iso
                    for s in nonsing:
                        E1 *= count_strict(*s, L)
                    chk("[E1-lit] Omegabar_C(P, L) = (L-1)^i prod s(K, L)", obL == E1)
                    chk("[E1-lit] Omegabar_C(P, L-1) = 0", omegabar_literal(n, rel, comps, T, L - 1) == 0)
                    # (b): strict f into [L] fails D_T iff some isolated point has value L
                    isol = [K[0] for K in comps if len(K) == 1]
                    okb = all(satisfies_DT(f, n, cl) == (not any(f[z] == L for z in isol))
                              for f in strict_maps(n, rel, L))
                    chk("[E1b-lit] D_T at [L] iff no isolated point has value L", okb)
                if L >= 3:
                    allstrict = strict_maps(n, rel, L + 1)
                    nDT = sum(1 for f in allstrict if satisfies_DT(f, n, cl))
                    prod_s = 1
                    for s in subs:
                        prod_s *= count_strict(*s, L + 1)
                    if all(l == L for l in LK):
                        chk("[E2-lit] all L_K = L >= 3: every strict map into [L+1] has D_T", nDT == len(allstrict))
                        chk("[E2-lit] ... and that count = prod s(K, L+1)", len(allstrict) == prod_s)
                    else:
                        ctl("[ctl-E2-mixed] E2 conclusion with mixed L_K", nDT != prod_s)
                        if nDT != prod_s and "E2mixed" not in examples:
                            examples["E2mixed"] = (n, sorted(rel), comps, nDT, prod_s)
                if r >= 2 and L >= 3:
                    # G via literal end coefficients: h_d = Omegabar(L), h_{d-1} = Omegabar(L+1) - (n+1) h_d
                    hd = omegabar_literal(n, rel, comps, T, L)
                    hd1 = omegabar_literal(n, rel, comps, T, L + 1) - (n + 1) * hd
                    if hd >= 2:
                        stats["hd>=2"] += 1
                        chk("[G-lit] r>=2, L>=3: h_d>=2 or gap", True)
                    else:
                        stats["hd=1"] += 1
                        prodJ = 1
                        for j in JK:
                            prodJ *= j
                        prod_s = 1
                        for s in subs:
                            prod_s *= count_strict(*s, L + 1)
                        gap = hd1 - h1_lit
                        okg = (hd == 1 and iso == 0 and all(l == L for l in LK)
                               and gap == prod_s - prodJ + 2 ** (r - 1) - 1
                               and gap >= 2 ** (r - 1) - 1 >= 1 and n - L >= 3)
                        if gap == 2 ** (r - 1) - 1:
                            stats["gap_attained"] += 1
                        chk("[G-lit] r>=2, L>=3: h_d>=2 or gap", okg)

            # ---- full h_C from the Moebius definition, n <= mobmax
            if n <= args.mobmax:
                a, signs_ok = omega_c_coeffs(n, rel)
                chk("[mob-sign] (-1)^{|pi|-1} mu(pi,1) >= 0", signs_ok)
                vals = [omega_c(a, m) for m in range(n + 2)]
                h = h_from_omega(n, vals)
                d = len(h) - 1
                pal = h == h[::-1]
                key = (tuple(h))
                # E0
                chk("[E0] h_0 = 1", h[0] == 1)
                h1 = h[1] if d >= 1 else 0
                chk("[E0] h_1 = J - 2^{r-1} - n", h1 == J - 2 ** (r - 1) - n)
                ctl("[ctl-h1-r] h_1 = J - n - 1", h1 != J - n - 1)
                # E1 / deg
                if L >= 2:
                    chk("[E1] d = n - L", d == n - L)
                    E1 = (L - 1) ** iso
                    for s in nonsing:
                        E1 *= count_strict(*s, L)
                    chk("[E1] h_d = (L-1)^i prod s(K,L)", h[d] == E1)
                # (R-bar) at small m, literal, and P0
                if L >= 2:
                    # Omegabar via reciprocity polynomial, then P0 equivalence
                    def obar(m):
                        return (-1) ** n * omega_c(a, -m)
                    s_ = L - 1
                    shift_ok = all(obar(m) == omega_c(a, m - s_) for m in range(0, n + 3))
                    chk("[P0] palindromic iff Omegabar(m) = Omega_C(m - L + 1)", shift_ok == pal)
                    if n <= args.litmax:
                        for m in range(0, n + 2):
                            lit = omegabar_literal(n, rel, comps, T, m)
                            chk("[Rbar-lit] sum h_j C(m+j,n) = literal Omegabar_C (n<=litmax)",
                                lit == sum(h[j] * comb(m + j, n) for j in range(len(h))))
                # E2 on h
                if L >= 3 and all(l == L for l in LK):
                    prod_s = 1
                    for s in subs:
                        prod_s *= count_strict(*s, L + 1)
                    hdm1 = h[d - 1] if d >= 1 else 0
                    chk("[E2] h_{d-1} + (n+1) h_d = prod s(K, L+1)", hdm1 + (n + 1) * h[d] == prod_s)
                if L == 2:
                    prod_s = 1
                    for s in subs:
                        prod_s *= count_strict(*s, L + 1)
                    hdm1 = h[d - 1] if d >= 1 else 0
                    ctl("[ctl-E2-L2] E2 identity at L = 2", hdm1 + (n + 1) * h[d] != prod_s)
                # connected case: Omega_C = Omega (all order-preserving maps), n <= litmax
                if connected and n <= args.litmax:
                    chk("[conn] connected: Omega_C(P,m) = Omega(P,m), m<=3",
                        all(vals[m] == len(weak_maps(n, rel, m)) for m in range(4)))
                # S' classification
                allh2 = all(l <= 2 for l in LK)
                predicted = (connected and graded) or allh2
                chk("[S'] palindromic iff (connected and graded) or all L_K <= 2", pal == predicted)
                if connected:
                    chk("[S'-conn] connected: palindromic iff graded", pal == graded)
                comp_graded = all(is_graded(*s) for s in subs)
                ctl("[ctl-graded] palindromic iff every component graded", pal != comp_graded)
                if pal != comp_graded and "graded" not in examples and r == 2 and n == 6:
                    examples["graded"] = (sorted(rel), h)
                if not connected and pal:
                    stats["pal_disc"][n] = stats["pal_disc"].get(n, 0) + 1
                # G on Moebius h
                if r >= 2 and L >= 3:
                    okG = h[d] >= 2 or (h[d] == 1 and h[d - 1] - h[1] >= 2 ** (r - 1) - 1 >= 1)
                    chk("[G] r>=2, L>=3: h_d >= 2 or h_{d-1} - h_1 >= 2^{r-1}-1", okG and not pal)
        print(f"n={n} done, {time.time() - t0:.1f}s", flush=True)

    # named examples
    def h_of(n, rel):
        a, _ = omega_c_coeffs(n, frozenset(rel))
        return h_from_omega(n, [omega_c(a, m) for m in range(n + 2)])
    C3C3 = {(0, 1), (1, 2), (0, 2), (3, 4), (4, 5), (3, 5)}
    print("h_C(C3 + C3) =", h_of(6, C3C3))
    print("h_C(C3 + C1) =", h_of(4, {(0, 1), (1, 2), (0, 2)}))
    print("h_C(C2 + C2) =", h_of(4, {(0, 1), (2, 3)}))
    print("examples:", examples)
    print("G split: h_d>=2:", stats["hd>=2"], " h_d=1:", stats["hd=1"],
          " gap attained:", stats["gap_attained"])
    print("palindromic disconnected per n (Moebius range):", stats["pal_disc"])

    bad = False
    print("\nCHECKS (name: checked / bad)")
    for k, (c, b) in checks.items():
        print(f"  {k}: {c} / {b}  {'PASS' if b == 0 else 'FAIL'}")
        bad |= b != 0
    print("CONTROLS (name: tested / refuted)")
    for k, (c, b) in controls.items():
        print(f"  {k}: {c} / {b}  {'REFUTED (good)' if b > 0 else 'NOT REFUTED (instrument blind)'}")
        bad |= b == 0
    print(f"total {time.time() - t0:.1f}s")
    sys.exit(1 if bad else 0)


if __name__ == "__main__":
    main()
